it('asserts valid input with an unlisted extra property is passed through to the executor unchanged', async () => {
  const registry = new ToolRegistry();
  let receivedInput: Record<string, unknown> | undefined;
  registry.register(
    {
      name: 'extra_props',
      description: 'test',
      inputSchema: {type: 'object', properties: {a: {type: 'string'}}},
    },
    async input => {
      receivedInput = input;
      return 'ok';
    }
  );

  it('keeps the usage an earlier round reported when a later round reports none', async () => {
    const usage: UsageMetadata = {inputTokens: 11, outputTokens: 3, totalTokens: 14};
    let seen: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, reported) => {
        seen = reported;
      },
    };
    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage}],
        [{type: 'text', text: 'done'}, STOP_DONE],
      ]),
      promptBuilder,
      registryReturning({result: 'r'}),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(seen).toEqual(usage);
  });

  it('feeds a schema rejection back to the provider as a tool_result so it can retry', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'test_tool',
        description: 'test',
        inputSchema: {type: 'object', properties: {age: {type: 'number'}}, required: ['age']},
      },
      async input => `Age is ${input.age}`
    );

    const roundsReceived: SendMessageParams[] = [];
    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        roundsReceived.push(params);
        if (roundsReceived.length === 1) {
          yield {
            type: 'tool_use',
            toolCall: {id: 'c1', name: 'test_tool', input: {age: 'not-a-number'}},
          };
          yield {type: 'stop', stopReason: 'tool_use'};
        } else {
          yield {type: 'text', text: 'fixed'};
          yield {type: 'stop', stopReason: 'end_turn'};
        }
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };

    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);
    await orchestrator.processMessage(createSession('start'));

    expect(roundsReceived).toHaveLength(2);
    const secondRoundMessages = roundsReceived[1].messages;
    const lastMessage = secondRoundMessages[secondRoundMessages.length - 1];
    expect(lastMessage.role).toBe('user');
    expect(Array.isArray(lastMessage.content)).toBe(true);
    const toolResult = (lastMessage.content as any[])[0];
    expect(toolResult.type).toBe('tool_result');
    expect(toolResult.content).toContain('Invalid input');
    expect(toolResult.content).toContain('age');
  });
});

